$path='performance/dist/style.css'
Add-Content $path @'
.roletabs{display:flex;gap:8px;padding:15px 34px 0;background:#fff;border-bottom:1px solid #dfe8ef;align-items:center}.roletabs button{border:0;border-bottom:3px solid transparent;border-radius:7px 7px 0 0;padding:12px 22px 14px;background:#f8fafc;text-align:left;font-size:12px;min-width:175px}.roletabs button small{font-size:10px;font-weight:400;margin-top:4px}.roletabs button.selected{color:#3686c6;background:#eef6fd;border-bottom-color:#549cdc}.roletabs>span{margin-left:auto;color:#a2afbb;font-size:9px;letter-spacing:1.3px}.scopebar{display:flex;align-items:center;justify-content:space-between;margin:-4px 0 24px;color:#8498a7;font-size:11px;gap:20px}.cyclepicker{display:flex;align-items:center;gap:12px;font-size:9px;letter-spacing:1px}.cyclepicker select{width:285px;padding:10px 12px;margin:0;border:1px solid #dbe5ed;border-radius:6px;color:#506b80;background:#fff;letter-spacing:0;font-size:11px}.chartgrid{display:grid;grid-template-columns:1fr 1.15fr;gap:22px;margin-bottom:22px}.chartpanel{min-height:295px}.chartpanel .panelhead{padding-bottom:8px}.chartpanel .panelhead .pill{font-size:9px}.donutwrap{display:flex;align-items:center;gap:22px;padding:18px 25px 28px}.donutwrap svg{width:180px;flex-shrink:0}.legend{flex:1}.legend>div{display:flex;align-items:center;gap:8px;font-size:11px;margin:18px 0}.legend i{width:8px;height:8px;border-radius:50%}.legend b{margin-left:auto}.barrow{grid-template-columns:135px 1fr 36px}.barrow>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.axis{display:flex;justify-content:space-between;margin:0 47px 0 150px;color:#9eafbd;font-size:9px;border-top:1px solid #edf1f5;padding-top:8px}.columnchart{display:flex;gap:25px;height:220px;padding:15px 35px 28px;align-items:end}.column{display:flex;flex-direction:column;align-items:center;flex:1;height:100%;gap:8px;font-size:10px;color:#8093a3}.column>b{font-size:12px;color:#4b6c86}.colwell{height:130px;width:100%;display:flex;align-items:flex-end;background:repeating-linear-gradient(to top,transparent 0px,transparent 31px,#eff3f6 32px)}.colwell i{display:block;width:60%;margin:auto auto 0;min-height:0;border-radius:4px 4px 0 0}.actionlist{padding:4px 23px 10px}.actionlist>div:not(.notice){display:flex;align-items:center;gap:12px;padding:18px 0;border-bottom:1px solid #edf1f5}.actionlist p{font-size:11px;margin-top:4px}.actionlist button{margin-left:auto;white-space:nowrap}.actionicon{color:#6da1cb;background:#edf5fc;border-radius:8px;padding:12px}.stat strong.smallmetric{font-size:19px;line-height:1.5;margin-top:16px}.scopebar+ .stats{margin-top:0}.lowercharts{grid-template-columns:1fr 1.15fr}@media(max-width:1150px){.chartgrid{grid-template-columns:1fr}.roletabs>span{display:none}.donutwrap{justify-content:center}.legend{max-width:300px}.roletabs button{min-width:145px;padding-left:14px;padding-right:14px}}@media(max-width:700px){.roletabs{padding:8px 10px 0;gap:4px}.roletabs button{min-width:0;flex:1;font-size:10px;padding:12px 8px}.roletabs small{display:none}.scopebar{align-items:flex-start;flex-direction:column;gap:12px}.cyclepicker{width:100%}.cyclepicker select{flex:1;width:auto}.chartgrid{gap:15px}.donutwrap{padding:15px;gap:12px}.donutwrap svg{width:145px}.legend>div{font-size:10px}.chartpanel .panelhead .pill{display:none}.barrow{grid-template-columns:95px 1fr 35px}.axis{margin-left:110px}.actionlist h3{font-size:12px}.actionicon{display:none}.stat strong.smallmetric{font-size:16px}.columnchart{gap:15px}.chartpanel{min-height:270px}}
'@
